function solve(elapsedHours, extension) {
  let expiresAt = 8;
  if (
    extension !== null &&
    typeof extension === 'object' &&
    extension.approver === 'incident-commander' &&
    Number.isFinite(extension.addedHours) &&
    extension.addedHours >= 0 &&
    extension.addedHours <= 2 &&
    Number.isFinite(extension.recordedAt) &&
    extension.recordedAt >= 0 &&
    extension.recordedAt < 8
  ) {
    expiresAt += extension.addedHours;
  }
  return elapsedHours < expiresAt;
}
